state.failing_test:
@given(
    st.integers(min_value=-20, max_value=20),
    st.integers(min_value=-20, max_value=20),
    st.integers(min_value=1, max_value=10),
)
def test_property_common_divisor_is_not_greater(a, b, d):
    # Any common divisor cannot exceed the gcd (for non-zero pair).
    g = greatest_common_divisor(a, b)
    if a == 0 and b == 0:
        return
    if d != 0 and a % d == 0 and b % d == 0:
        assert abs(d) <= g
